shell_commands:
cat >> src/orchestration/orchestratorHelpers.test.ts <<'EOF'

describe('addUsage', () => {
  it('sums each token field, skipping rounds that reported no usage and staying undefined when none did', () => {
    const rounds = [{inputTokens: 2, outputTokens: 1, totalTokens: 3}, undefined, {inputTokens: 7, outputTokens: 4, totalTokens: 11}];

    expect(rounds.reduce(addUsage, undefined)).toEqual({inputTokens: 9, outputTokens: 5, totalTokens: 14});
    expect([undefined, undefined].reduce(addUsage, undefined)).toBeUndefined();
  });
});
EOF
sed -i "1s/.*/import {addUsage, shouldContinueToolLoop} from '.\/orchestratorHelpers.js';/" src/orchestration/orchestratorHelpers.test.ts
sed -i "3s/.*/import type {ToolCall, UsageMetadata} from '..\/types\/ai.js';/" src/orchestration/orchestratorHelpers.test.ts
head -3 src/orchestration/orchestratorHelpers.test.ts; timeout 300 npx jest src/orchestration/orchestratorHelpers.test.ts 2>&1 | tail -15

cat >> src/orchestration/orchestratorHelpers.ts <<'EOF'

/** Adds one provider round's usage to a turn's running total; a round that reported none leaves the total unchanged. */
export function addUsage(total: UsageMetadata | undefined, round: UsageMetadata | undefined): UsageMetadata | undefined {
  if (!round) return total;
  if (!total) return round;
  return {
    inputTokens: total.inputTokens + round.inputTokens,
    outputTokens: total.outputTokens + round.outputTokens,
    totalTokens: total.totalTokens + round.totalTokens,
  };
}
EOF
sed -n 1,25p src/orchestration/chatOrchestrator.ts | grep -n "extractUsage"
sed -i 's/^  extractUsage,$/  addUsage,\n  extractUsage,/; s/let lastUsage: UsageMetadata | undefined;/let turnUsage: UsageMetadata | undefined;/; s/lastUsage = outcome.usage ?? lastUsage;/turnUsage = addUsage(turnUsage, outcome.usage);/; s/afterModelResponse(session, responseText, lastUsage)/afterModelResponse(session, responseText, turnUsage)/' src/orchestration/chatOrchestrator.ts
sed -n 15,30p src/orchestration/chatOrchestrator.ts; git diff --stat
